// Per-panel car meshes (workstream R): the procedural low-poly mesh of a car
// (data/panels/meshes/<car>.json, generated by tools/assets; formats 1–3) drawn as one batched
// Three.js mesh per material, every vertex skinned to its region's lattice nodes so dents show
// on every panel.
//
// Free panels (unlatched doors/hood/trunk, hanging bumpers/fenders) are rigid bodies in the sim:
// their lattice nodes are already rotated about the hinge. Plain displacement blending would
// smear a rotated door, so for those panels we fit the panel's rigid frame from three of its
// nodes (rest → current), take the dent in that frame and put the vertices back through it.
// Detached panels leave the car as visual debris (ballistic, bounce on the road; the physics
// debris body lives in Rapier and is not exposed to the browser yet).
//
// Cost: a re-skin only touches the parts whose lattice nodes moved since the last one, plus the
// parts of a swinging panel and the crumpling ones (`fold`); rigid parts (engine, suspension,
// `rigid: true`) are bound to one node with weight 1, so their skin is a plain translation (or
// the panel frame) inside their batch.
//
// Wheel-space parts: tire / rim / brake_disc spin (VehicleView puts `wheelParts` in its spin
// groups); caliper / upright steer and follow compression but do not spin (`pivotParts`, put in
// the wheel pivot groups).
//
// Livery: paint parts with material `livery` carry atlas UVs (layout: data/panels/README.md);
// `setLivery(texture)` maps a canvas onto them, `liveryPx()` converts car space to canvas pixels,
// `?livery=grid` in the URL shows `debugLiveryTexture()` on every car.
//
// Coordinates: chassis space (+X right, +Y forward, +Z up), metres. The parent VehicleView root
// is already in that frame.
import * as THREE from "three";
import { sim } from "../wasm/sim";
import { PALETTE } from "./palette";

/** Floats per panel in wasm `panel_states()` (mirrors crates/wp_wasm PANEL_STRIDE). */
export const PANEL_STRIDE = 10;
/** Panel state codes (mirrors wp_damage::PanelState::code). */
export const PANEL_STATE = { attached: 0, unlatched: 1, hanging: 2, detached: 3 } as const;

/** Part kinds (tools/assets/src/mesh.rs `PartKind`). */
export type PartKindJson =
  | "panel" | "glass" | "light" | "mirror" | "body" | "interior" | "tire" | "rim"
  | "detail" | "engine" | "suspension" | "brake_disc" | "caliper" | "upright" | "lightbar" | "decal_carrier";
/** Material slots (tools/assets/src/mesh.rs `MaterialSlot`). */
export type MaterialJson =
  | "paint" | "glass" | "trim" | "headlight" | "taillight" | "rubber" | "metal" | "interior"
  | "livery" | "chrome" | "carbon" | "caliper" | "engine" | "lightbar_red" | "lightbar_blue"
  | "lightbar_clear" | "emissive_amber" | "grille" | "exhaust" | "rim" | "spring" | "accent" | "underglow";

/** One part of data/panels/meshes/<car>.json (tools/assets/src/mesh.rs `MeshPart`). */
export interface MeshPartJson {
  name: string;
  region: string | null;
  kind: PartKindJson;
  material: MaterialJson;
  wheel?: number | null;
  /** Bound to one node with weight 255 (moves rigidly). */
  rigid?: boolean;
  positions_mm: number[];
  uvs: number[];
  indices: number[];
  skin_nodes: number[];
  skin_weights: number[];
  /** Hood / trunk lid / front fender / rear quarter crumple (format 3; tools/assets `FoldBinding`). */
  fold?: FoldJson;
}

/**
 * How a sheet panel crumples (tools/assets/src/mesh.rs `FoldBinding`, visual only): chords from
 * the fixed end (hinge row; side panel door-side row) to the leading end; the leading end follows the
 * crushed front structure (`leads`), the shortening becomes a fold along `dir`.
 */
export interface FoldJson {
  chords: [number, number][];
  /** Per chord: three front-structure nodes the leading end follows. */
  leads: [number, number, number][];
  /** Axis the chords spread along: 0 = x (lids), 2 = z (fenders). */
  across: number;
  dir: [number, number, number];
  /** Visual gain on the shortening (own chord loss or lead push, whichever is larger). */
  gain: number;
  max_m: number;
  /** Leading-edge pop once unlatched / hanging, m. */
  pop_m: number;
  /** 3 per vertex in 1/255: crease, fixed-end lift, leading-end follow. */
  weights: number[];
}

/** Lost chord length a panel absorbs before it buckles, m (mirrors tools/assets FOLD_DEAD_ZONE_M). */
const FOLD_DEAD_ZONE_M = 0.015;
/** Share of the single-tent height each lid ridge gets (FOLD_SPLIT). */
const FOLD_SPLIT = 0.7;
/** Fixed-edge lift of an unlatched lid, share of the fold height (FOLD_REAR_LIFT). */
const FOLD_REAR_LIFT = 0.45;
/** Largest leading-end pull-back, share of the chord length (FOLD_PULL_MAX). */
const FOLD_PULL_MAX = 0.5;
/** A node this close to rest (m) counts as at rest: the crumple memory clears (FOLD_REST_EPS_M). */
const FOLD_REST_EPS_M = 1e-3;
/** A light lens breaks once one of its vertices is pushed this far (m) by the crush. */
const LIGHT_BREAK_M = 0.05;

/**
 * Fold height (m, uncapped) of a sheet whose chord measured `rest` and is effectively `lost`
 * shorter: an inextensible strip pushed together rises into a tent (tools/assets `fold_height`).
 */
export function foldHeight(rest: number, lost: number): number {
  if (rest <= 1e-3) return 0;
  const l = Math.max(0, lost - FOLD_DEAD_ZONE_M);
  const k = 1 - Math.min(l / rest, 0.5);
  return 0.5 * rest * Math.sqrt(1 - k * k);
}

/** One chord's fold in the current pose (tools/assets `ChordFold`). */
interface ChordFold {
  at: number;
  height: number;
  extra: number;
  pop: number;
  u: [number, number, number];
}

/** Car-space box the livery atlas maps (mesh format 2). */
export interface LiveryAtlas {
  /** Tail y, nose y (m). */
  y: [number, number];
  /** Ground z, top z (m). */
  z: [number, number];
  /** Half width (m). */
  x_half: number;
}

/** Livery hint written by the style (tools/assets/src/style.rs `LiveryHint`). */
export interface LiveryHint {
  scheme: string;
  colors: [number, number, number][];
  text: string[];
}

/** data/panels/meshes/<car>.json (`CarMesh`). Format 1 files have none of the optional fields. */
export interface CarMeshJson {
  id: string;
  lattice_id: string;
  format: number;
  tri_count: number;
  tints?: Partial<Record<MaterialJson, [number, number, number]>>;
  livery?: LiveryHint;
  atlas?: LiveryAtlas;
  /** Visual camber per wheel (FL FR RL RR), degrees, + = top leans in. */
  wheel_camber_deg?: [number, number, number, number];
  parts: MeshPartJson[];
}

/** Wheel-space kinds that steer but do not spin (VehicleView's wheel pivots). */
const PIVOT_KINDS: ReadonlySet<PartKindJson> = new Set(["caliper", "upright"]);

const meshCache = new Map<string, Promise<CarMeshJson | null>>();
/** Meshes that finished loading (null = file missing), so a new car builds on its first frame. */
const meshLoaded = new Map<string, CarMeshJson | null>();
/** Fetch + parse time per car mesh, ms (`performance.now()` stamps), for the HUD / e2e. */
export const meshTimings = new Map<string, { start: number; end: number | null; ok: boolean }>();

/** Fetch (once per car) a car's panel mesh; null if the file is missing. */
export function loadCarMesh(carId: string): Promise<CarMeshJson | null> {
  let p = meshCache.get(carId);
  if (!p) {
    const timing = { start: performance.now(), end: null as number | null, ok: false };
    meshTimings.set(carId, timing);
    p = fetch(`data/panels/meshes/${carId}.json`)
      .then((r) => (r.ok ? (r.json() as Promise<CarMeshJson>) : null))
      .catch(() => null)
      .then((m) => {
        meshLoaded.set(carId, m);
        timing.end = performance.now();
        timing.ok = m !== null;
        return m;
      });
    meshCache.set(carId, p);
  }
  return p;
}

/** A car's mesh if it has already loaded (undefined while loading or never requested). */
export function carMeshNow(carId: string): CarMeshJson | null | undefined {
  return meshLoaded.get(carId);
}

/** Start loading every listed car mesh; resolves when all have arrived (or failed). */
export function preloadCarMeshes(carIds: string[]): Promise<void> {
  return Promise.all(carIds.map((id) => loadCarMesh(id))).then(() => undefined);
}

/** Panel states of an entity, PANEL_STRIDE floats per panel (empty if the build or scenario has none). */
export function panelStates(entity: number): Float32Array {
  try {
    return sim.panelStates(entity);
  } catch {
    return new Float32Array(0);
  }
}

// ------------------------------------------------------------------------------------------
// Livery atlas (layout: data/panels/README.md "Livery atlas")
// ------------------------------------------------------------------------------------------

/** Atlas band of a livery canvas. */
export type LiverySide = "left" | "right" | "top" | "front" | "rear";

const ATLAS_PAD = 0.004;
/** Band rectangles in UV space: [u0, u1, v0, v1] (v up, texture flipY = true). */
const BANDS: Record<LiverySide, [number, number, number, number]> = {
  left: [0, 0.25, 0, 0.5],
  right: [0.25, 0.5, 0, 0.5],
  top: [0, 0.5, 0.5, 0.8],
  front: [0, 0.25, 0.8, 1],
  rear: [0.25, 0.5, 0.8, 1],
};

/** Default atlas for format-1 meshes / before load (a 4.6 m × 1.9 m × 1.5 m car). */
export const DEFAULT_ATLAS: LiveryAtlas = { y: [-2.4, 2.4], z: [0, 1.75], x_half: 1.0 };

/**
 * Car space → livery UV (u, v in 0..1, v up). Arguments per side:
 * left/right: (y, z) — y forward, z up; top: (y, x); front/rear: (x, z). Metres, chassis space.
 * Mirrors tools/assets/src/mesh.rs `atlas_uv` exactly.
 */
export function liveryUv(atlas: LiveryAtlas, side: LiverySide, a: number, b: number): [number, number] {
  const clamp = (t: number) => Math.min(Math.max(t, 0), 1);
  const fy = (y: number) => clamp((y - atlas.y[0]) / (atlas.y[1] - atlas.y[0]));
  const fz = (z: number) => clamp((z - atlas.z[0]) / (atlas.z[1] - atlas.z[0]));
  const fx = (x: number) => clamp((x + atlas.x_half) / (2 * atlas.x_half));
  let s: number;
  let t: number;
  switch (side) {
    case "left": [s, t] = [1 - fy(a), fz(b)]; break; // nose at the band's left: reads front → rear
    case "right": [s, t] = [fy(a), fz(b)]; break; // tail at the band's left: reads rear → front
    case "top": [s, t] = [fy(a), 1 - fx(b)]; break; // plan view, nose right, car left at the top
    case "front": [s, t] = [1 - fx(a), fz(b)]; break; // seen from ahead
    case "rear": [s, t] = [fx(a), fz(b)]; break; // seen from behind
  }
  const [u0, u1, v0, v1] = BANDS[side];
  return [u0 + ATLAS_PAD + (u1 - u0 - 2 * ATLAS_PAD) * s, v0 + ATLAS_PAD + (v1 - v0 - 2 * ATLAS_PAD) * t];
}

/**
 * Car space → livery canvas pixel {x, y} (canvas origin top-left) for a canvas of `w` × `h`
 * pixels mapped over the whole texture (u 0..1). Arguments as `liveryUv`. Text drawn
 * left-to-right with plain `fillText` at a left/right-side anchor reads correctly from outside.
 */
export function liveryPx(
  atlas: LiveryAtlas, side: LiverySide, a: number, b: number, w: number, h: number,
): { x: number; y: number } {
  const [u, v] = liveryUv(atlas, side, a, b);
  return { x: u * w, y: (1 - v) * h };
}

/** Pixel rectangle {x, y, w, h} of an atlas band on a `w` × `h` canvas. */
export function liveryBandPx(side: LiverySide, w: number, h: number): { x: number; y: number; w: number; h: number } {
  const [u0, u1, v0, v1] = BANDS[side];
  return { x: u0 * w, y: (1 - v1) * h, w: (u1 - u0) * w, h: (v1 - v0) * h };
}

let debugLivery: THREE.CanvasTexture | null = null;

/** A labelled grid on every atlas band (to check the UV mapping): band names, FRONT arrows, 0.5 m grid. */
export function debugLiveryTexture(atlas: LiveryAtlas = DEFAULT_ATLAS): THREE.CanvasTexture {
  if (debugLivery) return debugLivery;
  const W = 2048;
  const H = 1024;
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d")!;
  g.fillStyle = "#777";
  g.fillRect(0, 0, W, H);
  const colours: Record<LiverySide, string> = {
    left: "#c33", right: "#36c", top: "#3a3", front: "#cc3", rear: "#c3c",
  };
  for (const side of Object.keys(BANDS) as LiverySide[]) {
    const r = liveryBandPx(side, W, H);
    g.fillStyle = colours[side];
    g.fillRect(r.x, r.y, r.w, r.h);
    g.strokeStyle = "rgba(255,255,255,0.6)";
    g.lineWidth = 2;
    // 0.5 m grid in car space.
    const lines: [number, number, number, number][] = [];
    if (side === "left" || side === "right" || side === "top") {
      for (let y = Math.ceil(atlas.y[0] * 2) / 2; y <= atlas.y[1]; y += 0.5) {
        const lo = side === "top" ? -atlas.x_half : atlas.z[0];
        const hi = side === "top" ? atlas.x_half : atlas.z[1];
        lines.push([y, lo, y, hi]);
      }
    }
    if (side !== "top") {
      for (let z = 0.5; z < atlas.z[1]; z += 0.5) {
        const a0 = side === "left" || side === "right" ? atlas.y[0] : -atlas.x_half;
        const a1 = side === "left" || side === "right" ? atlas.y[1] : atlas.x_half;
        lines.push([a0, z, a1, z]);
      }
    } else {
      lines.push([atlas.y[0], 0, atlas.y[1], 0]);
    }
    for (const [a0, b0, a1, b1] of lines) {
      const p0 = liveryPx(atlas, side, a0, b0, W, H);
      const p1 = liveryPx(atlas, side, a1, b1, W, H);
      g.beginPath();
      g.moveTo(p0.x, p0.y);
      g.lineTo(p1.x, p1.y);
      g.stroke();
    }
    g.fillStyle = "#fff";
    g.font = "bold 40px sans-serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
    const label = side.toUpperCase();
    // Anchors from car space: the arrow points toward the car's front on the sides / top.
    const mid = (atlas.y[0] + atlas.y[1]) / 2;
    const zMid = 0.75;
    const at =
      side === "left" || side === "right"
        ? liveryPx(atlas, side, mid, zMid, W, H)
        : side === "top"
          ? liveryPx(atlas, side, mid, 0.3, W, H)
          : liveryPx(atlas, side, 0, zMid, W, H);
    const front = side === "left" ? "◀ FRONT" : side === "right" || side === "top" ? "FRONT ▶" : "";
    g.fillText(`${label} ${front} ABC123`, at.x, at.y);
    if (side === "front" || side === "rear") {
      const l = liveryPx(atlas, side, -0.6, 0.5, W, H);
      g.font = "bold 28px sans-serif";
      g.fillText("CAR-LEFT", l.x, l.y);
    }
  }
  debugLivery = new THREE.CanvasTexture(c);
  debugLivery.colorSpace = THREE.SRGBColorSpace;
  return debugLivery;
}

function liveryFlag(): string | null {
  try {
    return new URLSearchParams(globalThis.location?.search ?? "").get("livery");
  } catch {
    return null;
  }
}

// ------------------------------------------------------------------------------------------

/** Per-part arrays derived from the car mesh file; identical for every car of a model, so they
 * are built once per part (browser perf, round 12b: promotions rebuilt them for each car). */
interface PartData {
  rest: Float32Array;
  weights: Float32Array;
  foldW: Float32Array;
  nodes: Uint16Array;
  index: Uint16Array | Uint32Array;
  /** Texture coordinates (0..1; livery atlas on `livery` parts). */
  uv: Float32Array;
  /** Distinct lattice nodes the part reads (weight > 0): change-only re-skin. */
  uniq: Uint16Array;
  /** Rest centroid, m (side of a lamp / light-bar lens: left = x < 0). */
  centre: THREE.Vector3;
  /** Wheel parts are never re-skinned: one geometry for every car of the model. */
  wheelGeom: THREE.BufferGeometry | null;
}
const partData = new WeakMap<MeshPartJson, PartData>();
function dataOf(def: MeshPartJson): PartData {
  let d = partData.get(def);
  if (d) return d;
  const n = def.positions_mm.length / 3;
  const rest = new Float32Array(n * 3);
  for (let i = 0; i < n * 3; i++) rest[i] = def.positions_mm[i] * 1e-3;
  const weights = new Float32Array(def.skin_weights.length);
  for (let i = 0; i < weights.length; i++) weights[i] = def.skin_weights[i] / 255;
  const fw = def.fold && def.fold.chords.length > 0 ? def.fold.weights : [];
  const foldW = new Float32Array(fw.length);
  for (let i = 0; i < fw.length; i++) foldW[i] = fw[i] / 255;
  const index = n > 65535 ? new Uint32Array(def.indices) : new Uint16Array(def.indices);
  const uv = new Float32Array(def.uvs.length);
  for (let i = 0; i < uv.length; i++) uv[i] = def.uvs[i] / 65535;
  const nodes = new Uint16Array(def.skin_nodes);
  const used = new Set<number>();
  for (let i = 0; i < nodes.length; i++) if (weights[i] > 0) used.add(nodes[i]);
  const centre = new THREE.Vector3();
  for (let i = 0; i < n; i++) centre.x += rest[i * 3] / n;
  for (let i = 0; i < n; i++) centre.y += rest[i * 3 + 1] / n;
  for (let i = 0; i < n; i++) centre.z += rest[i * 3 + 2] / n;
  let wheelGeom: THREE.BufferGeometry | null = null;
  if (def.wheel != null) {
    wheelGeom = new THREE.BufferGeometry();
    wheelGeom.setAttribute("position", new THREE.BufferAttribute(rest, 3));
    wheelGeom.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
    wheelGeom.setIndex(new THREE.BufferAttribute(index, 1));
  }
  d = { rest, weights, foldW, nodes, index, uv, uniq: Uint16Array.from(used), centre, wheelGeom };
  partData.set(def, d);
  return d;
}

/** Stand-in geometry of batched parts' own meshes (never drawn; see `PartRT.mesh`). */
const NO_GEOMETRY = new THREE.BufferGeometry();

/** Greybox values of every panel material, recorded when it is made (applyStyle restores them). */
const greyLook = new WeakMap<THREE.Material, { color: THREE.Color; roughness: number; metalness: number; opacity: number }>();
function std(o: THREE.MeshStandardMaterialParameters): THREE.MeshStandardMaterial {
  const m = new THREE.MeshStandardMaterial({ flatShading: true, side: THREE.DoubleSide, ...o });
  greyLook.set(m, { color: m.color.clone(), roughness: m.roughness, metalness: m.metalness, opacity: m.opacity });
  return m;
}
/** A light-bar lens (dark until flashed through `emissive`). */
const lens = (color: number) => std({ color, emissive: 0x000000, roughness: 0.3, transparent: true, opacity: 0.9, forceSinglePass: true });

/** Light-bar lens materials of one side. */
export interface LightbarSide {
  red: THREE.MeshStandardMaterial;
  blue: THREE.MeshStandardMaterial;
  clear: THREE.MeshStandardMaterial;
}

/** Head-lamp materials: one shared, or one per side (left = parts with x < 0) for wig-wag. */
export type LampMaterials = THREE.Material | { left: THREE.Material; right: THREE.Material };

/** Materials that are the same on every car: shared, so a promoted car adds few materials
 * (only paint, the lamps and the animated slots — livery, amber, light bar, underglow — are
 * per car, and per-model `tints` are per model). */
interface SharedMats {
  glass: THREE.MeshStandardMaterial;
  trim: THREE.MeshStandardMaterial;
  rubber: THREE.MeshStandardMaterial;
  metal: THREE.MeshStandardMaterial;
  interior: THREE.MeshStandardMaterial;
  brokenLamp: THREE.MeshStandardMaterial;
  chrome: THREE.MeshStandardMaterial;
  carbon: THREE.MeshStandardMaterial;
  caliper: THREE.MeshStandardMaterial;
  engine: THREE.MeshStandardMaterial;
  grille: THREE.MeshStandardMaterial;
  exhaust: THREE.MeshStandardMaterial;
  rim: THREE.MeshStandardMaterial;
  spring: THREE.MeshStandardMaterial;
  accent: THREE.MeshStandardMaterial;
  underglow: THREE.MeshStandardMaterial;
  amber: THREE.MeshStandardMaterial;
  lens: LightbarSide;
}
let sharedMats: SharedMats | null = null;
function shared(): SharedMats {
  return (sharedMats ??= {
    // forceSinglePass: a transparent DoubleSide material is otherwise drawn twice per part
    // (back faces, then front) and Three flips `side`, bumping the material version, so it
    // re-resolved the shader program for every glass part every frame (browser perf pass).
    glass: std({ color: 0x8fb3c4, transparent: true, opacity: 0.38, metalness: 0.1, roughness: 0.1, depthWrite: false, forceSinglePass: true }),
    trim: std({ color: 0x1b1b1d, roughness: 0.9 }),
    rubber: std({ color: 0x141414, roughness: 0.95 }),
    metal: std({ color: 0x9da3a8, metalness: 0.7, roughness: 0.35 }),
    interior: std({ color: 0x2b2724, roughness: 1 }),
    brokenLamp: std({ color: 0x2a2a2c, roughness: 0.6, metalness: 0.4 }),
    chrome: std({ color: 0xe8ecef, metalness: 1, roughness: 0.12 }),
    carbon: std({ color: 0x1e2124, metalness: 0.3, roughness: 0.35 }),
    // Calipers: dark grey unless the mesh tints them (`tints.caliper`).
    caliper: std({ color: 0x3a3c40, metalness: 0.2, roughness: 0.5 }),
    engine: std({ color: 0x3b3d40, metalness: 0.6, roughness: 0.6 }),
    grille: std({ color: 0x0d0e10, roughness: 0.8 }),
    exhaust: std({ color: 0xb9b2a6, metalness: 0.9, roughness: 0.25 }),
    // Rims / hubcaps: metal until the mesh tints them (`tints.rim`).
    rim: std({ color: 0x9da3a8, metalness: 0.7, roughness: 0.35 }),
    // Coil springs: tinted (`tints.spring`) or the old caliper grey.
    spring: std({ color: 0x3a3c40, metalness: 0.3, roughness: 0.5 }),
    // Second paint colour (stripes, accent bars): `tints.accent`.
    accent: std({ color: 0x8a1020, metalness: 0.25, roughness: 0.55 }),
    // Underglow strips of a car without an underglow colour: never lit.
    underglow: std({ color: 0x101012, emissive: 0x000000, roughness: 0.6 }),
    // Amber lenses of cars that never flash them (per car once the mesh has amber parts).
    amber: std({ color: 0xc87a10, emissive: 0x2a1600, roughness: 0.4 }),
    lens: { red: lens(0x661018), blue: lens(0x102266), clear: lens(0xbfc4c8) },
  });
}

/** Per-model materials of tinted slots (`tints`), key `<car id>:<slot>`. */
const tintCache = new Map<string, THREE.MeshStandardMaterial>();

/** Copy of `base` (greybox values) in colour `rgb` (sRGB bytes), recorded for applyStyle. */
function tintedCopy(base: THREE.Material, rgb: [number, number, number]): THREE.MeshStandardMaterial {
  const m = (base as THREE.MeshStandardMaterial).clone();
  const g = greyLook.get(base);
  if (g) {
    m.roughness = g.roughness;
    m.metalness = g.metalness;
    m.opacity = g.opacity;
  }
  m.color.setRGB(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255, THREE.SRGBColorSpace);
  greyLook.set(m, { color: m.color.clone(), roughness: m.roughness, metalness: m.metalness, opacity: m.opacity });
  return m;
}

/** Low-poly dark colours of the untinted fixed slots (render/palette.ts). */
const LOWPOLY_RGB: Partial<Record<MaterialJson, number>> = {
  glass: PALETTE.glass,
  trim: PALETTE.trim,
  rubber: PALETTE.tire,
  metal: PALETTE.rim,
  interior: PALETTE.interior,
  rim: PALETTE.rim,
  chrome: PALETTE.rim,
  exhaust: PALETTE.rim,
  carbon: PALETTE.trim,
  engine: PALETTE.trim,
  grille: PALETTE.trim,
  caliper: PALETTE.trim,
  spring: PALETTE.trim,
  lightbar_red: PALETTE.lightbarBase,
  lightbar_blue: PALETTE.lightbarBase,
  lightbar_clear: PALETTE.lightbarBase,
};

/** Merged index and UVs of one batch key's parts, per car model (the same for every car). */
const batchIndex = new WeakMap<CarMeshJson, Map<string, { index: Uint16Array | Uint32Array; uv: Float32Array }>>();

/** Largest-triangle node triples per region, per car model (from the rest lattice). */
const spanCache = new Map<string, Map<number, [number, number, number]>>();

interface PartRT {
  def: MeshPartJson;
  /** The part's own mesh: drawn for lenses (their material swaps when broken) and decal
   * carriers (per-unit decal material and UVs, render/livery.ts); for batched parts kept only
   * as a handle (material, name) and never drawn. */
  mesh: THREE.Mesh;
  /** Its material (the batch's for batched parts; a broken lens goes back to it on repair). */
  material: THREE.Material;
  /** Which batch it is drawn in: material slot, plus the side for per-side lamps / light bars. */
  batchKey: string;
  /** Skinned positions (chassis space). For a batched part a view into its batch's buffer. */
  pos: Float32Array;
  /** Merged draw of all parts with this part's material (null: drawn by `mesh`), and this
   * part's first index in it. */
  batch: Batch | null;
  indexStart: number;
  rest: Float32Array;
  nodes: Uint16Array;
  weights: Float32Array;
  uv: Float32Array;
  /** Distinct lattice nodes the part reads. */
  uniq: Uint16Array;
  /** Index into `info.regions`, -1 for wheel parts. */
  region: number;
  hidden: boolean;
  /** Was skinned through a free-panel frame last update (needs one more pass once it stops). */
  framed: boolean;
  /** Crumple binding (null: the part does not fold) and its per-vertex weights (0..1). */
  fold: FoldJson | null;
  foldW: Float32Array;
  /**
   * Crumple memory: per chord the largest effective shortening and leading-end pull-back seen
   * (m). Sheet metal does not spring back; cleared once the car is back at rest (repaired).
   */
  foldMem: Float32Array;
  /** Light lenses: broken (crushed or their bumper hangs), drawn dark without glow. */
  broken: boolean;
  /** Largest vertex displacement from rest at the last update, m (lights: break check; tests). */
  maxDisp: number;
  /** Largest fold rise at the last update, m (tests). */
  maxFold: number;
  /** Largest leading-end pull-back at the last update, m (tests). */
  maxPull: number;
}

/** skinVertices results: max squared displacement, max fold rise, max pull-back. */
const skinOut = new Float64Array(3);

/**
 * Re-skin one part's vertices into `pos` (chassis space): weighted node dents (in the panel's own
 * frame `f` when it is free), plus the crumple fold. A small standalone function so V8 optimises
 * it quickly: inside the big `update` it stayed in an unoptimised tier, where every float
 * operation allocated (~0.35 MB a frame with dented cars, browser-perf.md round 12b).
 */
function skinVertices(
  rest: Float32Array,
  pos: Float32Array,
  ids: Uint16Array,
  weights: Float32Array,
  nodes: Float32Array,
  rn: Float32Array,
  f: Frame | null,
  chords: ChordFold[] | null,
  fold: FoldJson | null,
  foldW: Float32Array,
  free: boolean,
  out: Float64Array,
): void {
  const nv = rest.length / 3;
  // Rotations as plain numbers (column-major Matrix3 elements).
  const rt = f ? f.rt.elements : null;
  const r = f ? f.r.elements : null;
  const tx = f ? f.t.x : 0;
  const ty = f ? f.t.y : 0;
  const tz = f ? f.t.z : 0;
  const across = fold ? fold.across : 0;
  const d0 = fold ? fold.dir[0] : 0;
  const d1 = fold ? fold.dir[1] : 0;
  const d2_ = fold ? fold.dir[2] : 0;
  const rearLift = free ? FOLD_REAR_LIFT : 0;
  let maxDisp = 0;
  let maxFold = 0;
  let maxPull = 0;
  for (let v = 0; v < nv; v++) {
    let dx = 0;
    let dy = 0;
    let dz = 0;
    for (let k = 0; k < 4; k++) {
      const w = weights[v * 4 + k];
      if (w === 0) continue;
      const i = ids[v * 4 + k] * 3;
      if (rt) {
        // Node in the panel's own frame, minus its rest position = dent.
        const x = nodes[i] - tx;
        const y = nodes[i + 1] - ty;
        const z = nodes[i + 2] - tz;
        dx += w * (rt[0] * x + rt[3] * y + rt[6] * z - rn[i]);
        dy += w * (rt[1] * x + rt[4] * y + rt[7] * z - rn[i + 1]);
        dz += w * (rt[2] * x + rt[5] * y + rt[8] * z - rn[i + 2]);
      } else {
        dx += w * (nodes[i] - rn[i]);
        dy += w * (nodes[i + 1] - rn[i + 1]);
        dz += w * (nodes[i + 2] - rn[i + 2]);
      }
    }
    if (chords) {
      // Buckle along the fold direction (crease, plus the fixed edge once free, plus the
      // leading-edge pop) and pull the leading end back with the crushed front.
      const c = foldAt(chords, rest[v * 3 + across]);
      const lead = foldW[v * 3 + 2];
      const rise = c.height * (foldW[v * 3] + rearLift * foldW[v * 3 + 1]) + c.pop * lead * lead;
      const pull = c.extra * lead;
      dx += d0 * rise - c.u[0] * pull;
      dy += d1 * rise - c.u[1] * pull;
      dz += d2_ * rise - c.u[2] * pull;
      if (rise > maxFold) maxFold = rise;
      if (pull > maxPull) maxPull = pull;
    }
    const x = rest[v * 3] + dx;
    const y = rest[v * 3 + 1] + dy;
    const z = rest[v * 3 + 2] + dz;
    if (r) {
      pos[v * 3] = r[0] * x + r[3] * y + r[6] * z + tx;
      pos[v * 3 + 1] = r[1] * x + r[4] * y + r[7] * z + ty;
      pos[v * 3 + 2] = r[2] * x + r[5] * y + r[8] * z + tz;
    } else {
      pos[v * 3] = x;
      pos[v * 3 + 1] = y;
      pos[v * 3 + 2] = z;
    }
    const ex = pos[v * 3] - rest[v * 3];
    const ey = pos[v * 3 + 1] - rest[v * 3 + 1];
    const ez = pos[v * 3 + 2] - rest[v * 3 + 2];
    const d2 = ex * ex + ey * ey + ez * ez;
    if (d2 > maxDisp) maxDisp = d2;
  }
  out[0] = maxDisp;
  out[1] = maxFold;
  out[2] = maxPull;
}

/**
 * One draw for every body part of a car that shares a material (browser perf, round 12b: a car
 * was ~37 draw calls, one per part). Parts skin straight into `position` through their `pos`
 * views; a hidden part (shattered, detached) has its index range collapsed to one vertex.
 */
interface Batch {
  mesh: THREE.Mesh;
  position: THREE.BufferAttribute;
  index: THREE.BufferAttribute;
  /** Re-skinned since the last upload. */
  dirty: boolean;
}

/** Element-wise equality of two float arrays. */
function sameFloats(a: Float32Array, b: Float32Array): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** Rigid frame of a free panel: x' = R x + t. */
interface Frame {
  r: THREE.Matrix3;
  rt: THREE.Matrix3;
  t: THREE.Vector3;
}

interface Debris {
  obj: THREE.Group;
  vel: THREE.Vector3;
  spin: THREE.Vector3;
  age: number;
}

const bodies = new Map<number, PanelBody>();
const debris: Debris[] = [];
const MAX_DEBRIS = 48;
const DEBRIS_LIFE_S = 40;
const WHITE = new THREE.Color(0xffffff);
const BLACK = new THREE.Color(0x000000);

/** Feed drained sim events (GlassShattered hides the glass part). Call once per frame. */
export function panelEvents(events: Record<string, Record<string, unknown>>[]): void {
  for (const e of events) {
    const g = e.GlassShattered;
    if (g) bodies.get(Number(g.vehicle))?.shatter(String(g.region));
  }
}

/** Advance visual debris (call once per frame with the frame dt). */
export function stepDebris(dt: number): void {
  for (let i = debris.length - 1; i >= 0; i--) {
    const d = debris[i];
    d.age += dt;
    d.vel.z -= 9.81 * dt;
    d.obj.position.addScaledVector(d.vel, dt);
    const e = new THREE.Euler(d.spin.x * dt, d.spin.y * dt, d.spin.z * dt);
    d.obj.quaternion.multiply(new THREE.Quaternion().setFromEuler(e));
    if (d.obj.position.z < 0.08) {
      d.obj.position.z = 0.08;
      if (d.vel.z < 0) d.vel.z = -0.25 * d.vel.z;
      d.vel.x *= 0.7;
      d.vel.y *= 0.7;
      d.spin.multiplyScalar(0.6);
    }
    if (d.age > DEBRIS_LIFE_S) {
      d.obj.removeFromParent();
      debris.splice(i, 1);
    }
  }
}

/** Remove all visual debris (scene reset). */
export function clearDebris(): void {
  for (const d of debris) d.obj.removeFromParent();
  debris.length = 0;
}

/** Number of visual debris pieces (tests / HUD). */
export function debrisCount(): number {
  return debris.length;
}

/** All per-panel meshes of one vehicle. Empty (ready = false) until the mesh file loads. */
export class PanelBody {
  /** Re-skins done since the page loaded, all cars (perf checks: should not grow while nothing
   * dents). */
  static reskins = 0;
  readonly root = new THREE.Group();
  ready = false;
  /** Spinning wheel-space parts per wheel index (tire, rim, brake disc), hub space: VehicleView puts them in its spin groups. */
  readonly wheelParts: THREE.Mesh[][] = [[], [], [], []];
  /** Steering, non-spinning wheel-space parts per wheel (caliper, upright): VehicleView puts them in its wheel pivots. */
  readonly pivotParts: THREE.Mesh[][] = [[], [], [], []];
  /** Visual camber per wheel, radians about +Y (sign already per side: + tilts the top toward +X). */
  readonly camberRad: number[] = [0, 0, 0, 0];
  /** Latest panel states (PANEL_STRIDE floats per panel). */
  states: Float32Array = new Float32Array(0);
  /** Livery atlas frame of this car (DEFAULT_ATLAS until the mesh loads / for format-1 files). */
  atlas: LiveryAtlas = DEFAULT_ATLAS;
  /** Livery hint from the mesh file, if any. */
  liveryHint: LiveryHint | null = null;
  /** Light-bar lens centres per side, chassis space (null if the car has none): place point lights here. */
  readonly lightbarAnchors: { left: THREE.Vector3 | null; right: THREE.Vector3 | null } = { left: null, right: null };
  /** Parts re-skinned in the last update() (perf / tests). */
  lastSkinned = 0;
  private parts: PartRT[] = [];
  /** Merged per-material draws of the body parts (`Batch`). */
  private batches: Batch[] = [];
  private readonly regions: string[];
  private restNodes: Float32Array = new Float32Array(0);
  /** Region index of every lattice node. */
  private nodeRegions: Uint8Array = new Uint8Array(0);
  /** Copy of the nodes of the last re-skin, and which nodes moved since (change-only re-skin). */
  private lastNodes: Float32Array | null = null;
  private nodeDirty: Uint8Array = new Uint8Array(0);
  /** Dark, unlit lens of a broken light. */
  private readonly brokenLamp: THREE.Material;
  /** Region index → three node ids spanning the panel (frame fit), for panel regions. */
  private readonly tri = new Map<number, [number, number, number]>();
  private readonly frames = new Map<number, Frame>();
  private readonly spawned = new Set<number>();
  /** Material per slot (shared, per model when tinted, or per car; see `shared()`). */
  private readonly mats: Record<MaterialJson, THREE.Material>;
  /** Right head lamp (the left one is `mats.headlight`; the same material without wig-wag). */
  private readonly headR: THREE.Material;
  /** Per-car light-bar lenses, made on first use. */
  private lightbars: { left: LightbarSide; right: LightbarSide } | null = null;
  /** Slots the mesh tints (kept in their tint by the low-poly style). */
  private readonly tinted = new Set<MaterialJson>();
  /** Underglow colour from the mesh tints (null: the car has none). */
  private underglowColour: THREE.Color | null = null;
  /** Soft additive glow on the road under the car (cars with underglow only). */
  private underglowPool: THREE.Mesh | null = null;
  private livery: THREE.Texture | null = null;
  /** Last applyStyle arguments (materials made when the mesh arrives get them too). */
  private lastStyle: { lowpoly: boolean; paint: THREE.Color } | null = null;
  private onReady: (() => void) | null = null;
  /** Nodes array of the last re-skin (VehicleView swaps in a new array only when they move). */
  private skinnedNodes: Float32Array | null = null;
  private readonly stateOf = new Map<number, number>();
  private disposed = false;

  constructor(
    readonly entity: number,
    readonly carId: string,
    paint: THREE.Color | number,
    headlight: LampMaterials,
    taillight: THREE.Material,
  ) {
    const headL = headlight instanceof THREE.Material ? headlight : headlight.left;
    this.headR = headlight instanceof THREE.Material ? headlight : headlight.right;
    this.regions = sim.info(entity).regions;
    const sm = shared();
    const paintMat = std({ color: paint, metalness: 0.25, roughness: 0.55 });
    this.mats = {
      paint: paintMat,
      // The paint until the mesh has livery parts (then a per-car material, see build).
      livery: paintMat,
      glass: sm.glass,
      trim: sm.trim,
      headlight: headL,
      taillight,
      rubber: sm.rubber,
      metal: sm.metal,
      interior: sm.interior,
      chrome: sm.chrome,
      carbon: sm.carbon,
      caliper: sm.caliper,
      engine: sm.engine,
      grille: sm.grille,
      exhaust: sm.exhaust,
      rim: sm.rim,
      spring: sm.spring,
      accent: sm.accent,
      underglow: sm.underglow,
      emissive_amber: sm.amber,
      lightbar_red: sm.lens.red,
      lightbar_blue: sm.lens.blue,
      lightbar_clear: sm.lens.clear,
    };
    this.brokenLamp = sm.brokenLamp;
    bodies.set(entity, this);
    // Preloaded (session start, render/fleet.ts): build now, so the car never shows a frame
    // without its mesh. Otherwise build when the file arrives — unless the car is gone by then
    // (a promoted traffic car demoted again between two frames; the view is disposed next frame).
    const now = carMeshNow(carId);
    if (now) this.build(now);
    else if (now === undefined)
      void loadCarMesh(carId).then((m) => {
        if (!m || this.disposed || bodies.get(entity) !== this) return;
        try {
          this.build(m);
        } catch {
          // wp_wasm: unknown entity — the sim already removed the vehicle.
        }
      });
  }

  /** Called once the mesh has loaded (immediately if it already has). */
  whenReady(fn: () => void): void {
    if (this.ready) fn();
    else this.onReady = fn;
  }

  /**
   * Art style (render/style.ts): low-poly dark takes paint, glass, trim, tire, rim, interior and
   * the other fixed slots' colours from the palette and makes every part matte (tinted slots
   * keep their tint); greybox restores the values above. Head/tail lamps are the VehicleView's
   * materials and are styled there.
   */
  applyStyle(lowpoly: boolean, paint: THREE.Color): void {
    this.lastStyle = { lowpoly, paint: paint.clone() };
    const seen = new Set<THREE.Material>();
    for (const [k, m] of Object.entries(this.mats) as [MaterialJson, THREE.Material][]) {
      if (k === "headlight" || k === "taillight" || seen.has(m)) continue;
      seen.add(m);
      this.styleOne(k, m, lowpoly, paint);
    }
    if (this.lightbars)
      for (const s of [this.lightbars.left, this.lightbars.right])
        for (const c of ["red", "blue", "clear"] as const) this.styleOne(`lightbar_${c}`, s[c], lowpoly, paint);
    const b = this.brokenLamp as THREE.MeshStandardMaterial;
    const bg = greyLook.get(b)!;
    b.color.copy(lowpoly ? new THREE.Color(PALETTE.brokenLight) : bg.color);
  }

  /** One slot's material in the art style (see applyStyle). */
  private styleOne(k: MaterialJson, m: THREE.Material, lowpoly: boolean, paint: THREE.Color): void {
    const g = greyLook.get(m);
    if (!g || !(m instanceof THREE.MeshStandardMaterial)) return;
    const body = k === "paint" || k === "livery";
    if (k === "paint") m.color.copy(lowpoly ? paint : g.color);
    // Livery: white under its texture, else the body colour (paint is styled first).
    else if (k === "livery") m.color.copy(this.livery ? WHITE : this.paint.color);
    else {
      const lp = this.tinted.has(k) ? undefined : LOWPOLY_RGB[k];
      m.color.copy(lowpoly && lp !== undefined ? new THREE.Color(lp) : g.color);
    }
    m.roughness = lowpoly ? (k === "glass" ? 0.35 : 0.85) : g.roughness;
    m.metalness = lowpoly ? (body ? 0.15 : 0) : g.metalness;
    // Low-poly glass is darker and less see-through (picker: near-opaque blue-black).
    if (k === "glass") m.opacity = lowpoly ? 0.82 : g.opacity;
  }

  /** Paint material (body colour). Set its opacity through `setBodyOpacity` (the livery follows). */
  get paint(): THREE.MeshStandardMaterial {
    return this.mats.paint as THREE.MeshStandardMaterial;
  }

  /** Livery material (paint parts that take the livery texture; the paint itself until the mesh has livery parts). */
  get liveryMaterial(): THREE.MeshStandardMaterial {
    return this.mats.livery as THREE.MeshStandardMaterial;
  }

  /** Fade the body (paint and livery) for the lattice view: 1 = opaque. */
  setBodyOpacity(opacity: number): void {
    const mats = this.mats.livery === this.mats.paint ? [this.paint] : [this.paint, this.liveryMaterial];
    for (const m of mats) {
      m.opacity = opacity;
      m.transparent = opacity < 1;
      m.depthWrite = !m.transparent;
    }
  }

  /**
   * The material of a slot (tints applied once the mesh loaded). Every part of that slot uses
   * it, except `headlight` on the right side when per-side lamps were given and the light-bar
   * lenses of the right side (see `lightbarMaterials`; this returns the left ones).
   */
  materialFor(slot: MaterialJson): THREE.Material {
    if (slot === "lightbar_red" || slot === "lightbar_blue" || slot === "lightbar_clear")
      return this.lightbarMaterials.left[slot.slice("lightbar_".length) as keyof LightbarSide];
    return this.mats[slot];
  }

  /** Light-bar lens materials per side (left = parts with x < 0), this car's own: flash them via `emissive`. */
  get lightbarMaterials(): { left: LightbarSide; right: LightbarSide } {
    if (!this.lightbars) {
      const side = (): LightbarSide => ({ red: lens(0x661018), blue: lens(0x102266), clear: lens(0xbfc4c8) });
      this.lightbars = { left: side(), right: side() };
      this.mats.lightbar_red = this.lightbars.left.red;
      this.mats.lightbar_blue = this.lightbars.left.blue;
      this.mats.lightbar_clear = this.lightbars.left.clear;
    }
    return this.lightbars;
  }

  /** This car's amber emissive material(s) (indicators, traffic advisors, beacons): flash via
   * `emissive`. Empty when the mesh has no amber parts (or is not loaded). */
  get amberMaterials(): THREE.MeshStandardMaterial[] {
    const m = this.mats.emissive_amber as THREE.MeshStandardMaterial;
    return m === shared().amber ? [] : [m];
  }

  /** True when the mesh has underglow strips (after load). */
  get hasUnderglow(): boolean {
    return this.underglowColour !== null;
  }

  /** Light (true) or darken the underglow strips; no-op for cars without underglow. */
  setUnderglow(on: boolean): void {
    if (!this.underglowColour) return;
    const m = this.mats.underglow as THREE.MeshStandardMaterial;
    m.emissive.copy(on ? this.underglowColour : BLACK);
    m.emissiveIntensity = on ? 1.6 : 1;
    if (this.underglowPool) this.underglowPool.visible = on;
  }

  /** Additive radial glow quad on the ground (chassis z ≈ 0) under the car's footprint. */
  private buildUnderglowPool(colour: THREE.Color): void {
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const g = c.getContext("2d");
    if (!g) return;
    const grad = g.createRadialGradient(32, 32, 4, 32, 32, 32);
    grad.addColorStop(0, "rgba(255,255,255,0.55)");
    grad.addColorStop(0.6, "rgba(255,255,255,0.22)");
    grad.addColorStop(1, "rgba(255,255,255,0)");
    g.fillStyle = grad;
    g.fillRect(0, 0, 64, 64);
    const tex = new THREE.CanvasTexture(c);
    const a = this.atlas;
    const geo = new THREE.PlaneGeometry(2 * a.x_half + 0.9, a.y[1] - a.y[0] + 0.6);
    const mat = new THREE.MeshBasicMaterial({
      color: colour,
      map: tex,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const pool = new THREE.Mesh(geo, mat);
    pool.name = "underglow_pool";
    pool.position.set(0, (a.y[0] + a.y[1]) / 2, 0.02);
    pool.renderOrder = 1;
    pool.visible = false;
    this.root.add(pool);
    this.underglowPool = pool;
  }

  /** Make the livery material this car's own (the paint stands in until then). */
  private ownLivery(): THREE.MeshStandardMaterial {
    if (this.mats.livery === this.mats.paint) {
      const g = greyLook.get(this.paint)!;
      const m = std({ color: g.color, metalness: g.metalness, roughness: g.roughness });
      m.color.copy(this.paint.color);
      this.mats.livery = m;
    }
    return this.liveryMaterial;
  }

  /**
   * Show `texture` (a canvas laid out as the livery atlas, see liveryPx) on the livery parts, or
   * go back to the plain body colour with null. The texture's colours are used as-is (white
   * material colour) while it is set.
   */
  setLivery(texture: THREE.Texture | null): void {
    this.livery = texture;
    const m = this.ownLivery();
    m.map = texture;
    m.color.copy(texture ? WHITE : this.paint.color);
    m.needsUpdate = true;
  }

  /** Mesh `tints`: per-model copies of the shared slots, per-car colours of the animated ones. */
  private applyTints(mesh: CarMeshJson): void {
    for (const [slot, rgb] of Object.entries(mesh.tints ?? {}) as [MaterialJson, [number, number, number] | undefined][]) {
      if (!rgb || !(slot in this.mats)) continue;
      const colour = new THREE.Color().setRGB(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255, THREE.SRGBColorSpace);
      switch (slot) {
        case "underglow":
          // Emissive colour, lit by setUnderglow (VehicleView: with the headlights).
          this.underglowColour = colour;
          this.mats.underglow = std({ color: 0x101012, emissive: 0x000000, roughness: 0.6 });
          break;
        // Body colour and lamps belong to the view (traffic palette, art style).
        case "paint":
        case "headlight":
        case "taillight":
          break;
        case "livery":
          this.ownLivery().color.copy(colour);
          break;
        case "emissive_amber":
          this.mats.emissive_amber = tintedCopy(shared().amber, rgb);
          break;
        case "lightbar_red":
        case "lightbar_blue":
        case "lightbar_clear": {
          const c = slot.slice("lightbar_".length) as keyof LightbarSide;
          for (const s of [this.lightbarMaterials.left, this.lightbarMaterials.right]) {
            s[c].color.copy(colour);
            greyLook.get(s[c])?.color.copy(colour);
          }
          break;
        }
        default: {
          const key = `${mesh.id}:${slot}`;
          let m = tintCache.get(key);
          if (!m) tintCache.set(key, (m = tintedCopy(this.mats[slot], rgb)));
          this.mats[slot] = m;
          this.tinted.add(slot);
        }
      }
    }
  }

  /** Material of a part (`side` from its rest centroid: per-side head lamps and light-bar lenses). */
  private materialOf(def: MeshPartJson, side: "left" | "right"): THREE.Material {
    const slot = def.material;
    if (slot === "headlight") return side === "left" ? this.mats.headlight : this.headR;
    if (slot === "lightbar_red" || slot === "lightbar_blue" || slot === "lightbar_clear")
      return this.lightbarMaterials[side][slot.slice("lightbar_".length) as keyof LightbarSide];
    if (slot === "livery") return this.ownLivery();
    if (slot === "emissive_amber" && this.mats.emissive_amber === shared().amber) {
      // Amber lenses flash per car (police advisors, beacons): this car's own material.
      this.mats.emissive_amber = std({ color: 0xc87a10, emissive: 0x2a1600, roughness: 0.4 });
    }
    return this.mats[slot] ?? this.mats.paint; // unknown slot (newer file) → paint
  }

  private build(mesh: CarMeshJson): void {
    this.restNodes = sim.latticeRest(this.entity);
    this.nodeDirty = new Uint8Array(this.restNodes.length / 3);
    const nodeRegions = sim.latticeRegions(this.entity);
    this.nodeRegions = nodeRegions;
    let spans = spanCache.get(this.carId);
    if (!spans) spanCache.set(this.carId, (spans = new Map()));
    if (mesh.atlas) this.atlas = mesh.atlas;
    this.liveryHint = mesh.livery ?? null;
    this.applyTints(mesh);
    (mesh.wheel_camber_deg ?? [0, 0, 0, 0]).forEach((deg, i) => {
      // Wheels 0, 2 are on the left (−X): + camber tilts their top toward +X.
      const left = i % 2 === 0;
      this.camberRad[i] = ((left ? 1 : -1) * deg * Math.PI) / 180;
    });
    const lbSum = { left: new THREE.Vector3(), right: new THREE.Vector3() };
    const lbCount = { left: 0, right: 0 };
    for (const def of mesh.parts) {
      const d = dataOf(def);
      const region = def.region ? this.regions.indexOf(def.region) : -1;
      const side = d.centre.x < 0 ? "left" : "right";
      const material = this.materialOf(def, side);
      const perSide = def.material === "headlight" || def.material.startsWith("lightbar_");
      if (def.material.startsWith("lightbar_")) {
        lbSum[side].add(d.centre);
        lbCount[side]++;
      }
      if (d.wheelGeom) {
        // Wheel parts follow VehicleView's wheel groups (spin, or pivot only for calipers /
        // uprights) and are never re-skinned.
        const wm = new THREE.Mesh(d.wheelGeom, material);
        wm.name = def.name;
        wm.frustumCulled = false;
        (PIVOT_KINDS.has(def.kind) ? this.pivotParts : this.wheelParts)[def.wheel!].push(wm);
        continue;
      }
      const pos = d.rest.slice();
      // Lenses and decal carriers keep their own mesh (broken lenses swap material; decals get
      // per-unit materials and UVs, render/livery.ts applyUnitDecals); every other body part is
      // drawn by its material's batch (buildBatches) and keeps a never-drawn handle mesh.
      let m: THREE.Mesh;
      if (def.kind === "light" || def.kind === "decal_carrier") {
        const geom = new THREE.BufferGeometry();
        geom.setAttribute("position", new THREE.BufferAttribute(pos, 3));
        geom.setAttribute("uv", new THREE.BufferAttribute(d.uv.slice(), 2));
        geom.setIndex(new THREE.BufferAttribute(d.index, 1));
        // Lenses use the shared head/tail materials (not flat-shaded): without a normal attribute
        // their shading turns NaN and the lens renders black, glow included.
        if (def.kind === "light") geom.computeVertexNormals();
        m = new THREE.Mesh(geom, material);
        m.frustumCulled = false;
        this.root.add(m);
      } else {
        m = new THREE.Mesh(NO_GEOMETRY, material);
      }
      m.name = def.name;
      const fold = def.fold && def.fold.chords.length > 0 ? def.fold : null;
      this.parts.push({
        def,
        mesh: m,
        material,
        batchKey: perSide ? `${def.material}:${side}` : def.material,
        pos,
        batch: null,
        indexStart: 0,
        rest: d.rest,
        nodes: d.nodes,
        weights: d.weights,
        uv: d.uv,
        uniq: d.uniq,
        region,
        hidden: false,
        framed: false,
        fold,
        foldW: d.foldW,
        foldMem: new Float32Array((fold?.chords.length ?? 0) * 2),
        broken: false,
        maxDisp: 0,
        maxFold: 0,
        maxPull: 0,
      });
      if (region >= 0 && !this.tri.has(region)) {
        let t = spans.get(region);
        if (!t) spans.set(region, (t = spanTriangle(this.restNodes, nodeRegions, region)));
        this.tri.set(region, t);
      }
    }
    for (const side of ["left", "right"] as const)
      if (lbCount[side] > 0) this.lightbarAnchors[side] = lbSum[side].divideScalar(lbCount[side]);
    if (this.underglowColour) this.buildUnderglowPool(this.underglowColour);
    this.buildBatches(mesh);
    this.ready = true;
    // Materials made just now (tints, livery, amber, light bar) take the current art style.
    if (this.lastStyle) this.applyStyle(this.lastStyle.lowpoly, this.lastStyle.paint);
    if (liveryFlag() === "grid") this.setLivery(debugLiveryTexture(this.atlas));
    this.update(this.restNodes, 0);
    this.onReady?.();
  }

  /** Merge the non-lens body parts into one mesh per material (see `Batch`). */
  private buildBatches(mesh: CarMeshJson): void {
    let cached = batchIndex.get(mesh);
    if (!cached) batchIndex.set(mesh, (cached = new Map()));
    const groups = new Map<string, PartRT[]>();
    for (const p of this.parts) {
      if (p.mesh.geometry !== NO_GEOMETRY) continue; // own mesh (lens, decal carrier)
      let g = groups.get(p.batchKey);
      if (!g) groups.set(p.batchKey, (g = []));
      g.push(p);
    }
    for (const [key, parts] of groups) {
      let nv = 0;
      let ni = 0;
      for (const p of parts) {
        nv += p.rest.length / 3;
        ni += p.def.indices.length;
      }
      const pos = new Float32Array(nv * 3);
      // The merged index and UVs are the same for every car of the model: build them once,
      // copy the index per car (hidden parts are collapsed in the copy).
      let tmpl = cached.get(key);
      if (!tmpl) {
        const index = nv > 65535 ? new Uint32Array(ni) : new Uint16Array(ni);
        const uv = new Float32Array(nv * 2);
        let v = 0;
        let i = 0;
        for (const p of parts) {
          const idx = p.def.indices;
          for (let k = 0; k < idx.length; k++) index[i + k] = idx[k] + v;
          if (p.uv.length === (p.rest.length / 3) * 2) uv.set(p.uv, v * 2);
          v += p.rest.length / 3;
          i += idx.length;
        }
        cached.set(key, (tmpl = { index, uv }));
      }
      const index = tmpl.index.slice();
      let v0 = 0;
      let i0 = 0;
      for (const p of parts) {
        pos.set(p.pos, v0 * 3);
        p.pos = pos.subarray(v0 * 3, v0 * 3 + p.rest.length);
        p.indexStart = i0;
        v0 += p.rest.length / 3;
        i0 += p.def.indices.length;
      }
      const geom = new THREE.BufferGeometry();
      const position = new THREE.BufferAttribute(pos, 3);
      const indexAttr = new THREE.BufferAttribute(index, 1);
      geom.setAttribute("position", position);
      // UVs: the livery atlas (other slots carry them too, unused without a map).
      geom.setAttribute("uv", new THREE.BufferAttribute(tmpl.uv, 2));
      geom.setIndex(indexAttr);
      const material = parts[0].material;
      const mesh = new THREE.Mesh(geom, material);
      mesh.name = `${this.carId}:${key}`;
      mesh.frustumCulled = false;
      if (key === "glass" || key.startsWith("lightbar_")) mesh.renderOrder = 1;
      this.root.add(mesh);
      const batch: Batch = { mesh, position, index: indexAttr, dirty: false };
      for (const p of parts) p.batch = batch;
      this.batches.push(batch);
    }
  }

  /** Stop drawing a part (shattered glass, detached panel). */
  private hidePart(p: PartRT): void {
    p.hidden = true;
    p.mesh.visible = false;
    const b = p.batch;
    if (!b) return;
    // Collapse its triangles onto one vertex (degenerate: nothing rasterised).
    const idx = b.index.array as Uint16Array | Uint32Array;
    const first = idx[p.indexStart];
    idx.fill(first, p.indexStart, p.indexStart + p.def.indices.length);
    b.index.needsUpdate = true;
  }

  /** Hide a shattered glass region. */
  shatter(region: string): void {
    for (const p of this.parts) {
      if (p.def.region === region && p.def.kind === "glass") this.hidePart(p);
    }
  }

  /**
   * Re-skin the parts whose nodes moved (or whose panel swings, or that crumple) from the
   * current lattice nodes (chassis space, xyz per node) and the panel states. `worldVel` (the
   * car's world velocity, m/s) seeds detached-panel debris.
   */
  update(nodes: Float32Array, dt: number, worldVel?: THREE.Vector3): void {
    if (!this.ready) return;
    const states = panelStates(this.entity);
    const statesSame = sameFloats(states, this.states);
    // Same nodes and panel states as the last re-skin: every vertex would come out the same.
    if (nodes === this.skinnedNodes && statesSame) {
      this.lastSkinned = 0;
      return;
    }
    this.skinnedNodes = nodes;
    this.states = states;
    PanelBody.reskins++;
    // Which nodes moved since the last re-skin (all of them on the first).
    const last = this.lastNodes;
    const dirty = this.nodeDirty;
    if (!last || last.length !== nodes.length) {
      dirty.fill(1);
      this.lastNodes = nodes.slice();
    } else {
      for (let i = 0; i < dirty.length; i++) {
        const j = i * 3;
        dirty[i] = nodes[j] !== last[j] || nodes[j + 1] !== last[j + 1] || nodes[j + 2] !== last[j + 2] ? 1 : 0;
      }
      last.set(nodes);
    }
    this.frames.clear();
    for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) {
      const region = this.states[k];
      const state = this.states[k + 1];
      if (state === PANEL_STATE.unlatched || state === PANEL_STATE.hanging) {
        const tri = this.tri.get(region);
        if (tri) this.frames.set(region, fitFrame(this.restNodes, nodes, tri));
      } else if (state === PANEL_STATE.detached && !this.spawned.has(region)) {
        this.spawned.add(region);
        if (dt > 0) this.spawnDebris(region, worldVel ?? new THREE.Vector3());
        else this.hideRegion(region);
      }
    }
    const rn = this.restNodes;
    // Panel state per region index (absent = no panel there, i.e. fixed structure).
    const stateOf = this.stateOf;
    stateOf.clear();
    for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) stateOf.set(this.states[k], this.states[k + 1]);
    let skinned = 0;
    for (const p of this.parts) {
      if (p.hidden) continue;
      const f = p.region >= 0 ? this.frames.get(p.region) : undefined;
      // Change-only: a part none of whose nodes moved comes out the same — unless its panel
      // swings (or just stopped), it crumples (lead nodes, memory) or a panel state changed
      // (lenses break when their bumper hangs).
      if (statesSame && !f && !p.framed && !p.fold) {
        let touched = false;
        for (let i = 0; i < p.uniq.length && !touched; i++) touched = dirty[p.uniq[i]] === 1;
        if (!touched) continue;
      }
      p.framed = f !== undefined;
      skinned++;
      const { rest, pos, nodes: ids, weights } = p;
      const state = stateOf.get(p.region);
      const free = state === PANEL_STATE.unlatched || state === PANEL_STATE.hanging;
      const chords = p.fold ? this.chordFolds(p, nodes, f, free, stateOf) : null;
      const r = skinOut;
      skinVertices(rest, pos, ids, weights, nodes, rn, f ?? null, chords, p.fold, p.foldW, free, r);
      const maxDisp = r[0];
      const maxFold = r[1];
      const maxPull = r[2];
      p.maxDisp = Math.sqrt(maxDisp);
      p.maxFold = maxFold;
      p.maxPull = maxPull;
      if (p.batch) p.batch.dirty = true;
      else (p.mesh.geometry.getAttribute("position") as THREE.BufferAttribute).needsUpdate = true;
      if (p.def.kind === "light") {
        this.updateLight(p, stateOf);
        if (p.maxDisp > 1e-4) p.mesh.geometry.computeVertexNormals();
      }
    }
    this.lastSkinned = skinned;
    for (const b of this.batches) {
      if (!b.dirty) continue;
      b.dirty = false;
      b.position.needsUpdate = true;
    }
  }

  /**
   * Fold values per chord of a crumpling part (mirrors tools/assets `skin::chord_folds`): the
   * larger of the own chord loss (panel frame) and the lead push (chassis space, a hanging
   * bumper's nodes taken back to their attached pose), times the visual gain, ratcheted in the
   * part's crumple memory.
   */
  private chordFolds(p: PartRT, nodes: Float32Array, f: Frame | undefined, free: boolean, stateOf: Map<number, number>): ChordFold[] {
    const fold = p.fold!;
    const rn = this.restNodes;
    const tmp = new THREE.Vector3();
    // Node `i` in the panel's own frame (chassis space when attached).
    const local = (i: number): [number, number, number] => {
      if (!f) return [nodes[i * 3], nodes[i * 3 + 1], nodes[i * 3 + 2]];
      tmp.set(nodes[i * 3] - f.t.x, nodes[i * 3 + 1] - f.t.y, nodes[i * 3 + 2] - f.t.z).applyMatrix3(f.rt);
      return [tmp.x, tmp.y, tmp.z];
    };
    const off = (i: number) => Math.hypot(nodes[i * 3] - rn[i * 3], nodes[i * 3 + 1] - rn[i * 3 + 1], nodes[i * 3 + 2] - rn[i * 3 + 2]);
    const atRest = fold.chords.every(([a, b]) => off(a) <= FOLD_REST_EPS_M && off(b) <= FOLD_REST_EPS_M) && fold.leads.every((l) => l.every((i) => off(i) <= FOLD_REST_EPS_M));
    if (atRest) p.foldMem.fill(0);
    // Lead node as if its panel were still attached: a hanging panel's node rotated back by its
    // hang angle about its pivot (the sim captures the hanging pose at angle 0, so this is the
    // crushed pose it was released in); null once its panel fell off (tools/assets `lead_pos`).
    const leadPos = (i: number): [number, number, number] | null => {
      const r = this.nodeRegions[i];
      const st = stateOf.get(r);
      if (st === PANEL_STATE.detached) return null;
      const at: [number, number, number] = [nodes[i * 3], nodes[i * 3 + 1], nodes[i * 3 + 2]];
      if (st !== PANEL_STATE.hanging) return at;
      for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) {
        if (this.states[k] !== r) continue;
        const s = this.states;
        const pivot = new THREE.Vector3(s[k + 4], s[k + 5], s[k + 6]);
        const axis = new THREE.Vector3(s[k + 7], s[k + 8], s[k + 9]);
        const v = new THREE.Vector3(...at).sub(pivot).applyAxisAngle(axis, -s[k + 2]).add(pivot);
        return [v.x, v.y, v.z];
      }
      return at;
    };
    return fold.chords.map(([a, b], c) => {
      const ru = [rn[b * 3] - rn[a * 3], rn[b * 3 + 1] - rn[a * 3 + 1], rn[b * 3 + 2] - rn[a * 3 + 2]];
      const la = Math.max(Math.hypot(ru[0], ru[1], ru[2]), 1e-4);
      const u: [number, number, number] = [ru[0] / la, ru[1] / la, ru[2] / la];
      const la_ = local(a);
      const lb = local(b);
      const own = la - Math.hypot(lb[0] - la_[0], lb[1] - la_[1], lb[2] - la_[2]);
      let pushLatch = 0;
      for (let k = 0; k < 3; k++) pushLatch -= (lb[k] - rn[b * 3 + k] - (la_[k] - rn[a * 3 + k])) * u[k];
      const dl = [0, 0, 0];
      let n = 0;
      for (const l of fold.leads[c]) {
        const at = leadPos(l);
        if (!at) continue;
        for (let k = 0; k < 3; k++) dl[k] += at[k] - rn[l * 3 + k];
        n++;
      }
      let pushLead = pushLatch;
      if (n > 0) {
        pushLead = 0;
        for (let k = 0; k < 3; k++) pushLead -= (dl[k] / n - (nodes[a * 3 + k] - rn[a * 3 + k])) * u[k];
      }
      const eff = Math.max(fold.gain * Math.max(own, pushLead), p.foldMem[c * 2]);
      const extra = Math.max(pushLead - pushLatch, 0, p.foldMem[c * 2 + 1]);
      p.foldMem[c * 2] = eff;
      p.foldMem[c * 2 + 1] = extra;
      return {
        at: rn[b * 3 + fold.across],
        height: Math.min(FOLD_SPLIT * foldHeight(la, eff), fold.max_m),
        extra: Math.min(extra, FOLD_PULL_MAX * la),
        pop: free ? fold.pop_m : 0,
        u,
      };
    });
  }

  /**
   * A light lens breaks (dark, no glow) once the crush pushes it LIGHT_BREAK_M or the panel it
   * is bound to hangs or falls off. Stateless, so a repaired car gets its lights back.
   */
  private updateLight(p: PartRT, stateOf: Map<number, number>): void {
    let broken = p.maxDisp > LIGHT_BREAK_M;
    for (let k = 0; !broken && k < p.nodes.length; k++) {
      const s = stateOf.get(this.nodeRegions[p.nodes[k]]);
      broken = s === PANEL_STATE.hanging || s === PANEL_STATE.detached;
    }
    if (broken !== p.broken) {
      p.broken = broken;
      p.mesh.material = broken ? this.brokenLamp : p.material;
    }
  }

  /** Per-part motion at the last update (tests): largest displacement, fold rise and leading-end pull-back, m. */
  partMotion(name: string): { disp: number; fold: number; pull: number; broken: boolean } | null {
    const p = this.parts.find((q) => q.def.name === name);
    return p ? { disp: p.maxDisp, fold: p.maxFold, pull: p.maxPull, broken: p.broken } : null;
  }

  /** Light lenses: name, broken, and whether they show the shared head/tail material. */
  lights(): { name: string; broken: boolean; material: THREE.Material; visible: boolean }[] {
    return this.parts
      .filter((p) => p.def.kind === "light")
      .map((p) => ({ name: p.def.name, broken: p.broken, material: p.mesh.material as THREE.Material, visible: !p.hidden && p.mesh.visible }));
  }

  private hideRegion(region: number): void {
    for (const p of this.parts) {
      if (p.region === region) this.hidePart(p);
    }
  }

  /**
   * Centre (chassis space, current dented shape) of `region`'s parts (any region: `null`) made
   * of `material` (`glass`, `headlight`, `taillight`), written to `out`. False when the mesh has
   * none (or is not loaded). Used by the crash effects (render/fx) to burst shards there.
   */
  materialCentre(region: string | null, material: MaterialJson, out: THREE.Vector3): boolean {
    let x = 0;
    let y = 0;
    let z = 0;
    let n = 0;
    for (const p of this.parts) {
      if ((region !== null && p.def.region !== region) || p.def.material !== material) continue;
      const pos = p.pos;
      for (let i = 0; i < pos.length; i += 3) {
        x += pos[i];
        y += pos[i + 1];
        z += pos[i + 2];
      }
      n += pos.length / 3;
    }
    if (n === 0) return false;
    out.set(x / n, y / n, z / n);
    return true;
  }

  /** Move a detached region's parts out of the car into world-space debris. */
  private spawnDebris(region: number, worldVel: THREE.Vector3): void {
    const parent = this.root.parent?.parent; // VehicleView.root → world group
    const car = this.root.parent;
    if (!parent || !car) return this.hideRegion(region);
    const group = new THREE.Group();
    group.position.copy(car.position);
    group.quaternion.copy(car.quaternion);
    const centroid = new THREE.Vector3();
    let count = 0;
    for (const p of this.parts) {
      if (p.region !== region || p.hidden) continue;
      const geom = new THREE.BufferGeometry();
      geom.setAttribute("position", new THREE.BufferAttribute(p.pos.slice(), 3));
      // UVs so livery / decal textures stay on the debris.
      const uv = p.mesh.geometry.getAttribute("uv") as THREE.BufferAttribute | undefined;
      if (uv) geom.setAttribute("uv", uv);
      else if (p.uv.length === (p.rest.length / 3) * 2) geom.setAttribute("uv", new THREE.BufferAttribute(p.uv, 2));
      geom.setIndex(p.def.indices);
      const m = new THREE.Mesh(geom, p.mesh.material);
      m.frustumCulled = false;
      group.add(m);
      for (let i = 0; i < p.pos.length; i += 3) {
        centroid.x += p.pos[i];
        centroid.y += p.pos[i + 1];
        centroid.z += p.pos[i + 2];
        count++;
      }
      this.hidePart(p);
    }
    if (count === 0) return;
    centroid.multiplyScalar(1 / count);
    // Pivot the debris about its own centre so it tumbles believably.
    for (const c of group.children) c.position.sub(centroid);
    group.position.add(centroid.clone().applyQuaternion(car.quaternion));
    parent.add(group);
    // Thrown outward from the car's centre, a little up; spin from the region index (deterministic).
    const out = new THREE.Vector3(centroid.x, centroid.y, 0).normalize().applyQuaternion(car.quaternion);
    const vel = worldVel.clone().addScaledVector(out, 1.5);
    vel.z += 1.2;
    const s = (region % 5) - 2;
    debris.push({ obj: group, vel, spin: new THREE.Vector3(1.5 + s * 0.4, -1.0 + s * 0.3, 0.8 - s * 0.2), age: 0 });
    while (debris.length > MAX_DEBRIS) debris.shift()?.obj.removeFromParent();
  }

  dispose(): void {
    this.disposed = true;
    if (bodies.get(this.entity) === this) bodies.delete(this.entity);
    this.root.removeFromParent();
    for (const ps of [...this.wheelParts, ...this.pivotParts]) for (const m of ps) m.removeFromParent();
  }
}


/** Scratch result of `foldAt` (it runs per vertex of every folded part on each re-skin; a new
 * object per vertex was ~0.5 MB of garbage per frame in a crash, browser-perf.md). */
const foldScratch: ChordFold = { at: 0, height: 0, extra: 0, pop: 0, u: [0, 0, 0] };

/** Chord fold values at across coordinate `x`, linear between chords (sorted by `at`). The
 * result is a chord of `cs` or a shared scratch object, valid until the next call. */
function foldAt(cs: ChordFold[], x: number): ChordFold {
  if (x <= cs[0].at) return cs[0];
  for (let i = 1; i < cs.length; i++) {
    if (x <= cs[i].at) {
      const a = cs[i - 1];
      const b = cs[i];
      const t = (x - a.at) / Math.max(b.at - a.at, 1e-4);
      const o = foldScratch;
      o.at = x;
      o.height = a.height + (b.height - a.height) * t;
      o.extra = a.extra + (b.extra - a.extra) * t;
      o.pop = a.pop + (b.pop - a.pop) * t;
      o.u = a.u;
      return o;
    }
  }
  return cs[cs.length - 1];
}

/** Three nodes of `region` spanning the largest triangle (rest pose). */
function spanTriangle(rest: Float32Array, regions: Uint8Array, region: number): [number, number, number] {
  const ids: number[] = [];
  for (let i = 0; i < regions.length; i++) if (regions[i] === region) ids.push(i);
  let best: [number, number, number] = [ids[0] ?? 0, ids[1] ?? 0, ids[2] ?? 0];
  let area = -1;
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  for (let i = 0; i < ids.length; i++)
    for (let j = i + 1; j < ids.length; j++)
      for (let k = j + 1; k < ids.length; k++) {
        a.fromArray(rest, ids[i] * 3);
        b.fromArray(rest, ids[j] * 3).sub(a);
        c.fromArray(rest, ids[k] * 3).sub(a);
        const ar = b.cross(c).lengthSq();
        if (ar > area) {
          area = ar;
          best = [ids[i], ids[j], ids[k]];
        }
      }
  return best;
}

/** Orthonormal frame of a node triangle as columns. */
function triFrame(p: Float32Array, [i, j, k]: [number, number, number]): { m: THREE.Matrix3; o: THREE.Vector3 } {
  const o = new THREE.Vector3().fromArray(p, i * 3);
  const e1 = new THREE.Vector3().fromArray(p, j * 3).sub(o).normalize();
  const c = new THREE.Vector3().fromArray(p, k * 3).sub(o);
  const e3 = new THREE.Vector3().crossVectors(e1, c).normalize();
  const e2 = new THREE.Vector3().crossVectors(e3, e1);
  const m = new THREE.Matrix3().set(e1.x, e2.x, e3.x, e1.y, e2.y, e3.y, e1.z, e2.z, e3.z);
  return { m, o };
}

/** Rigid transform taking the triangle's rest frame to its current frame. */
function fitFrame(rest: Float32Array, cur: Float32Array, tri: [number, number, number]): Frame {
  const a = triFrame(rest, tri);
  const b = triFrame(cur, tri);
  const r = b.m.clone().multiply(a.m.clone().transpose());
  const t = b.o.clone().sub(a.o.clone().applyMatrix3(r));
  return { r, rt: r.clone().transpose(), t };
}
